export function renderManagedReviewerProviderPrompt(basePrompt: string, canonicalRoot: string): string {
  const primaryWorktree = canonicalRoot.trim();
  if (!primaryWorktree) return basePrompt;
  return basePrompt
    .split(/\r?\n/)
    .filter(line => {
